from pysnooper.utils import get_repr_function


def test_get_repr_function_empty_custom_repr_returns_builtin_repr():
    result = get_repr_function(123, [])

    assert result is repr
    assert result(123) == repr(123)


def test_get_repr_function_type_condition_match_returns_action():
    def action(item):
        return f"int:{item}"

    result = get_repr_function(42, [(int, action)])

    assert result is action
    assert result(42) == "int:42"


def test_get_repr_function_type_condition_no_match_returns_repr():
    def action(item):
        return f"int:{item}"

    result = get_repr_function("hello", [(int, action)])

    assert result is repr
    assert result("hello") == repr("hello")


def test_get_repr_function_type_condition_matches_subclass_instance():
    class Animal:
        pass

    class Dog(Animal):
        pass

    def action(item):
        return "animal"

    result = get_repr_function(Dog(), [(Animal, action)])

    assert result is action
    assert result(Dog()) == "animal"


def test_get_repr_function_callable_condition_match_returns_action():
    def action(item):
        return f"big:{item}"

    result = get_repr_function(10, [(lambda x: x > 5, action)])

    assert result is action
    assert result(10) == "big:10"


def test_get_repr_function_callable_condition_no_match_returns_repr():
    def action(item):
        return f"big:{item}"

    result = get_repr_function(3, [(lambda x: x > 5, action)])

    assert result is repr
    assert result(3) == repr(3)


def test_get_repr_function_skips_non_matching_and_returns_later_match():
    def str_action(item):
        return f"str:{item}"

    def int_action(item):
        return f"int:{item}"

    def positive_action(item):
        return f"positive:{item}"

    custom_repr = [
        (str, str_action),
        (lambda x: isinstance(x, int) and x < 0, positive_action),
        (int, int_action),
    ]

    result = get_repr_function(42, custom_repr)

    assert result is int_action
    assert result(42) == "int:42"


def test_get_repr_function_first_matching_condition_wins():
    def first_action(item):
        return "first"

    def second_action(item):
        return "second"

    custom_repr = [
        (int, first_action),
        (lambda x: True, second_action),
    ]

    result = get_repr_function(7, custom_repr)

    assert result is first_action
    assert result(7) == "first"
